import{_ as o,r as s,o as p,c as l,e as a,a as c,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Group Scope - October CMS - 4.x","titleTemplate":false,"description":"Filter Scope","frontmatter":{"subtitle":"Filter Scope","shortname":"Group"},"headers":[{"level":2,"title":"PHP Interface","slug":"php-interface","link":"#php-interface","children":[]}],"relativePath":"4.x/element/filter/scope-group.md","filePath":"4.x/element/filter/scope-group.md"}'),r={name:"4.x/element/filter/scope-group.md"};function i(d,n,k,g,y,m){const e=s("pre-heading"),t=s("post-heading");return p(),l("div",null,[a(e),n[0]||(n[0]=c("h1",null,"Group Scope",-1)),a(t),n[1]||(n[1]=u(`<p><code>group</code> - filter using a group of multiple items, usually by a related model or an array of predefined options.</p><p>To filter by a model, specify the <code>modelClass</code> and <code>nameFrom</code> properties to specify which model and attribute to use.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> October\\Test\\Models\\Role
</code></pre></div><p>The following properties are available for the filter.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>options</strong></td><td>available options for the filter, as an array.</td></tr><tr><td><strong>optionsMethod</strong></td><td>take options from a method defined on the model or as a static method, eg <code>Class::method</code>.</td></tr><tr><td><strong>optionsScope</strong></td><td>applies a <a href="./../filter-scopes.html">model scope method</a> to the options query.</td></tr><tr><td><strong>conditions</strong></td><td>a custom SQL select statement to use for the filter.</td></tr><tr><td><strong>nameFrom</strong></td><td>the column name to use in the model class, used for displaying the name. Default: <code>name</code>.</td></tr><tr><td><strong>modelClass</strong></td><td>class of the model to use for the available filter records.</td></tr><tr><td><strong>modelScope</strong></td><td>applies a <a href="./../filter-scopes.html">model scope method</a> to the filter query.</td></tr><tr><td><strong>matchMode</strong></td><td>determines how the selection should be applied, either <code>include</code>, <code>exclude</code> or <code>toggle</code>. Default: <code>include</code></td></tr></tbody></table></div><p>To filter by an array, specify an <code>options</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">developer</span><span class="token punctuation">:</span> Developer
        <span class="token key atrule">publisher</span><span class="token punctuation">:</span> Publisher
</code></pre></div><p>You may pass custom SQL to the conditions as a string where <code>:value</code> contains the filtered value.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> role in (<span class="token punctuation">:</span>value)
    <span class="token comment"># ...</span>
</code></pre></div><p>You may also pass a <code>default</code> value as an array with selected keys.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
    <span class="token comment"># ...</span>
    <span class="token key atrule">default</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> developer
        <span class="token punctuation">-</span> publisher
</code></pre></div><p>Use the <code>matchMode</code> property control how the filter is applied, either by including or excluding the selected items.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
    <span class="token comment"># ...</span>
    <span class="token key atrule">matchMode</span><span class="token punctuation">:</span> toggle
</code></pre></div><h2 id="php-interface"><a href="#php-interface" class="header-anchor">#</a> PHP Interface</h2><p>You may define a custom <code>modelScope</code> in the model using the following example.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> October\\Test\\Models\\Role
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> groupFilter
</code></pre></div><p>The <strong>scopeGroupFilter</strong> method definition where the value is found in <code>$scope-&gt;value</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeGroupFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereHas</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;roles&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$q</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$scope</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$q</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may dynamically supply options by passing a model method to the <code>optionsMethod</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> October\\Test\\Models\\Role
    <span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getRoleGroupOptions
</code></pre></div><p>The <strong>getRoleGroupOptions</strong> method definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getRoleGroupOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">whereNull</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">pluck</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>optionsScope</code> property allows you to apply a scope to the default query that locates the available options.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> October\\Test\\Models\\Role
    <span class="token key atrule">optionsScope</span><span class="token punctuation">:</span> applyRoleOptionsFilter
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyRoleOptionsFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,25))])}const v=o(r,[["render",i]]);export{f as __pageData,v as default};
